	            if (i == 30) {
	                thread.start();
	            }
	            if(i == 40){
	                myRunnable.stopThread();
	            }
	        }
	    }
	}

	class MyRunnable implements Runnable {

	    private boolean stop;

	    @Override
	    public void run() {
	        for (int i = 0; i < 100 && !stop; i++) {
	            System.out.println(Thread.currentThread().getName() + " " + i);
	        }
	    }

	    public void stopThread() {
	        this.stop = true;
	    }

	}

